method.description:
Converts Godot data to YAML and saves it to a file at the specified path. Returns a [YAMLResult] containing either the YAML string that was written or error information.
If [param style] is provided, it will be used to customize the formatting of the YAML output. Otherwise, default formatting will be used.
[codeblocks]
[gdscript]
# Save data to a YAML file
var data = {
		"settings": {
				"volume": 0.8,
				"fullscreen": true
		},
		"player": {
				"name": "Hero",
				"level": 5
		}
}

var result = YAML.save_file(data, "user://settings.yaml")
if result.has_error():
		print("Error saving file: ", result.get_error_message())
else:
		print("File saved successfully")
[/gdscript]
[/codeblocks]
